$workerScript = @'
const cf = require('cloudflare Workers');
cf.dns.setTTL(300); // Set TTL to 5 minutes
cf.dns.setQueryType('A'); // Set query type to A records

// Define the tunnel endpoint
const tunnelEndpoint = 'https://example.cloudflare.com';

// Define the DNS query handler
cf.dns.on('query', (event) => {
    const query = event.request;
    const response = cf.dns.response(query);

    // Tunnel the query through Cloudflare
    fetch(tunnelEndpoint + '/api/v4/dns/records/' + query.name + '/A', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
